#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-10-09

# Test: target-taking skills resolve a pronoun from the conversation (#3780)
#
# `/ork:assess them` refused with "them has no antecedent" one message after
# the subject was named. The fix is one shared rule,
# src/shared/rules/target-resolution.md, read by every skill that takes a
# target. An inline skill resolves the reference and announces it. A forked
# skill cannot see the conversation, so it returns the sentinel
# TARGET_UNRESOLVED: <word> before it dispatches any agent, and the caller
# resolves and re-invokes.
#
# This checks the wiring only. The behaviour needs a real model run, which CI
# does not make.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"

RULE="$REPO_ROOT/src/shared/rules/target-resolution.md"
READ_LINE='Read("../../shared/rules/target-resolution.md")'
SKILLS="assess verify implement fix-issue cover review-pr"

FAILED=0
fail() { echo "FAIL: $1"; FAILED=1; }

# Print the value of a top-level frontmatter key, or nothing if absent.
fm_value() {
  awk -v key="$2" '
    NR == 1 && $0 == "---" { inside = 1; next }
    inside && $0 == "---" { exit }
    inside && index($0, key ":") == 1 {
      v = substr($0, length(key) + 2)
      gsub(/^[ \t"]+|[ \t"]+$/, "", v)
      print v
      exit
    }' "$1"
}

# Line number of the first line containing a fixed string, or 0.
first_fixed() {
  awk -v s="$1" 'index($0, s) { print NR; found = 1; exit } END { if (!found) print 0 }' "$2"
}

# Line number of the first agent dispatch (Agent( or Workflow( call), or 0.
first_dispatch() {
  awk '/Agent\(|Workflow\(/ { print NR; found = 1; exit } END { if (!found) print 0 }' "$1"
}

# (d) the rule exists and has both halves.
if [[ ! -f "$RULE" ]]; then
  fail "missing src/shared/rules/target-resolution.md"
else
  [[ "$(awk '/^#+ .*Inline skills/ { n++ } END { print n + 0 }' "$RULE")" -gt 0 ]] \
    || fail "rule has no 'Inline skills' section"
  [[ "$(awk '/^#+ .*Forked skills/ { n++ } END { print n + 0 }' "$RULE")" -gt 0 ]] \
    || fail "rule has no 'Forked skills' section"
  [[ "$(first_fixed 'TARGET_UNRESOLVED: <word>' "$RULE")" -gt 0 ]] \
    || fail "rule does not define the TARGET_UNRESOLVED sentinel"
fi

for name in $SKILLS; do
  md="$REPO_ROOT/src/skills/$name/SKILL.md"
  [[ -f "$md" ]] || { fail "$name: SKILL.md not found"; continue; }

  # (a) every target-taking skill reads the shared rule.
  read_at="$(first_fixed "$READ_LINE" "$md")"
  if [[ "$read_at" -eq 0 ]]; then
    fail "$name: does not $READ_LINE"
    continue
  fi

  # (b) a forked skill checks the target before it dispatches anything.
  if [[ "$(fm_value "$md" context)" == "fork" ]]; then
    dispatch_at="$(first_dispatch "$md")"
    [[ "$dispatch_at" -gt 0 ]] || dispatch_at=999999
    sentinel_at="$(first_fixed 'TARGET_UNRESOLVED' "$md")"
    if [[ "$sentinel_at" -eq 0 ]]; then
      fail "$name: forked skill never names TARGET_UNRESOLVED"
    elif (( sentinel_at > dispatch_at )); then
      fail "$name: TARGET_UNRESOLVED (line $sentinel_at) comes after the first dispatch (line $dispatch_at)"
    fi
    if (( read_at > dispatch_at )); then
      fail "$name: rule Read (line $read_at) comes after the first dispatch (line $dispatch_at)"
    fi
  fi
done

# (c) no skill keeps its own copy of the rule.
for md in "$REPO_ROOT"/src/skills/*/SKILL.md; do
  if [[ "$(first_fixed 'resolve a conversational reference' "$md")" -gt 0 ]]; then
    fail "own copy of the rule in ${md#"$REPO_ROOT"/}"
  fi
done

echo ""
if [[ $FAILED -eq 0 ]]; then
  echo "OK: 6 target-taking skills read target-resolution.md; forked skills check the target before dispatch"
fi
exit "$FAILED"
